using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace CastleFight {
public sealed partial class PcGame {
    JObject corruptedFxIndex;JArray corruptedArtAspects;
    readonly Dictionary<string,GameObject> corruptedFxPrefabs=new Dictionary<string,GameObject>();
    readonly Dictionary<string,PcModel> corruptedAttachments=new Dictionary<string,PcModel>();
    void LoadCorruptedArt(){if(corruptedFxIndex!=null)return;var asset=ContentResources.Load<TextAsset>("corrupted-fx-index");corruptedFxIndex=asset?JObject.Parse(asset.text):new JObject();corruptedArtAspects=corruptedPack?(JArray)JObject.Parse(corruptedPack.catalog.text)["aspects"]:new JArray();}
    GameObject CorruptedFx(string key,int team){if(string.IsNullOrEmpty(key))return null;string id=key+"-"+team;if(!corruptedFxPrefabs.TryGetValue(id,out var prefab)){prefab=ContentResources.Load<GameObject>("CorruptedFx/"+id);corruptedFxPrefabs[id]=prefab;}return prefab;}
    void ResolveCorruptedDefaultColors(){LoadCorruptedArt();if(!(corruptedFxIndex["defaultWhite"] is JObject defaults))return;foreach(var p in defaults.Properties())for(int team=0;team<2;team++){var prefab=CorruptedFx(p.Name,team);if(!prefab)continue;foreach(var skin in prefab.GetComponentsInChildren<SkinnedMeshRenderer>())foreach(int i in (JArray)p.Value){var m=skin.sharedMaterials[i];if(m&&!m.mainTexture)m.mainTexture=Texture2D.whiteTexture;}}}
    GameObject CorruptedMissile(HumanMatch.Shot shot){if(match==null)return null;LoadCorruptedArt();string key=null;if((shot.weapon?.missile??"").StartsWith("corrupted:"))key=(string)corruptedFxIndex["visuals"]?[shot.weapon.missile.Substring(10)]?["missile"]?[0]?["key"];else {string raw=shot.sourceId>=0?match.Units.FirstOrDefault(u=>u.id==shot.sourceId) is HumanMatch.Unit u?match.Lines[u.kind].unit:null:null;key=(string)corruptedFxIndex["weapons"]?[raw+"_1"];if(key==null&&shot.line>=0&&shot.line<match.Lines.Length)key=(string)corruptedFxIndex["weapons"]?[match.Lines[shot.line].building+"_1"]??(string)corruptedFxIndex["weapons"]?[match.Lines[shot.line].unit+"_1"];}return CorruptedFx(key,shot.team);}
    void PlaceCorrupted(HashSet<string> wanted,string id,string key,int team,Vector3 point,Vector2 direction=default){var prefab=CorruptedFx(key,team);if(!prefab)return;wanted.Add(id);if(!corruptedAttachments.TryGetValue(id,out var model)||!model){model=Instantiate(prefab,visuals.transform).GetComponent<PcModel>();if(!model.particleOnly)model.Play(model.clips.Any(c=>c.name.StartsWith("Stand"))?"Stand":model.clips[0].name);corruptedAttachments[id]=model;}model.transform.position=point;if(direction.sqrMagnitude>0)model.Face(direction);}
    Vector3 CorruptedAnchor(PcModel view,string attachment){LoadCorruptedArt();var tokens=(attachment??"origin").ToLowerInvariant().Split(new[]{',',' '},StringSplitOptions.RemoveEmptyEntries);var point=(corruptedFxIndex["attachments"]?[view.raw]?["points"] as JArray??new JArray()).FirstOrDefault(p=>tokens.All(t=>((string)p["name"]).ToLowerInvariant().Contains(t)));if(point==null)return view.transform.position;var offset=(JArray)point["offset"];var v=new Vector3(-(float)offset[0],(float)offset[1],(float)offset[2]);string bone=(string)point["bone"];var node=view.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name==bone);return node?node.TransformPoint(v):view.animatedRoot.transform.TransformPoint(v);}
    void CorruptedBuff(HashSet<string> wanted,string prefix,PcModel view,int team,string ability){int i=0;foreach(var art in corruptedFxIndex["visuals"]?[ability]?["buff"] as JArray??new JArray()){string id=prefix+"-"+ability+"-"+i++;PlaceCorrupted(wanted,id,(string)art["key"],team,CorruptedAnchor(view,(string)art["attach"]));if(corruptedAttachments.TryGetValue(id,out var effect)&&new[]{"A04M","A051","A053","A058"}.Contains(ability)){float native=HumanMatch.F(match.Lines.First(l=>l.building==view.raw||l.unit==view.raw).building==view.raw?match.Lines.First(l=>l.building==view.raw).buildingStats:match.Lines.First(l=>l.unit==view.raw).stats,"model_scale",1);effect.transform.localScale=Vector3.one*native/Mathf.Max(.001f,view.animatedRoot.transform.localScale.x);}}}
    void RenderCorruptedEffects(){LoadCorruptedArt();var wanted=new HashSet<string>();
        foreach(var u in match.Units)if(u.hp>0&&units.TryGetValue(u.id,out var view)){
            view.transform.position+=Vector3.up*match.CorruptedLift(u);
            foreach(string ability in u.abilities.Where(id=>id=="A053"||id=="A058"))CorruptedBuff(wanted,"innate-"+u.id,view,u.team,ability);
            foreach(string ability in u.effects.Where(e=>e.left>0).Select(e=>e.id=="corrupted_impale_air"?"A0AF":e.id).Concat(u.auraIds).Distinct())CorruptedBuff(wanted,"status-"+u.id,view,u.team,ability);
            if(match.TeamCorrupted[u.team]&&match.Aspects[u.team]>=0){var aspect=(JObject)corruptedArtAspects[match.Aspects[u.team]];PlaceCorrupted(wanted,"aspect-"+u.id,(string)aspect["visual"]?["buff"]?["key"],u.team,view.transform.position);}
        }
        foreach(var h in match.Huts)if(huts.TryGetValue(h.id,out var view)){
            foreach(string ability in match.Lines[h.kind].abilities.Where(id=>id=="A04M"||id=="A051"))CorruptedBuff(wanted,"building-"+h.id,view,h.team,ability);
            int i=0;foreach(var row in corruptedFxIndex["decorations"]?[match.Lines[h.kind].building] as JArray??new JArray()){string raw=(string)row[0];foreach(var art in corruptedFxIndex["visuals"]?["corrupted_decor_"+raw]?["effect"] as JArray??new JArray()){var point=view.transform.TransformPoint(new Vector3((float)row[2]/30,raw=="h04J"?-20f/30:raw=="h09Z"?50f/30:0,-(float)row[3]/30));string id="decor-"+h.id+"-"+i++;PlaceCorrupted(wanted,id,(string)art["key"],h.team,point);if(corruptedAttachments.TryGetValue(id,out var effect)){effect.transform.rotation=view.transform.rotation*Quaternion.Euler(0,90-(float)row[1],0);var profile=corruptedFxIndex["decorProfiles"]?[raw];effect.transform.localScale=Vector3.one*HumanMatch.F(profile,"scale",1);var tint=(JArray)profile?["tint"];if(tint!=null)foreach(var renderer in effect.GetComponentsInChildren<SkinnedMeshRenderer>())for(int m=0;m<renderer.sharedMaterials.Length;m++){var block=new MaterialPropertyBlock();renderer.GetPropertyBlock(block,m);block.SetColor("_Tint",new Color((float)tint[0],(float)tint[1],(float)tint[2],(float)tint[3]));renderer.SetPropertyBlock(block,m);}}}}
        }
        foreach(var wave in match.CorruptedWaves){string key=(string)corruptedFxIndex["visuals"]?["A04X"]?["missile"]?[0]?["key"];PlaceCorrupted(wanted,"wave-"+wave.id,key,wave.team,World(wave.origin+wave.direction*wave.distance)+Vector3.up,wave.direction);}
        foreach(var pulse in match.Pulses){if(!(pulse.fx??"").StartsWith("corrupted:"))continue;var split=pulse.fx.Split(':');if(split.Length!=3)continue;int i=0;JArray art=split[1]=="rot"?new JArray(new JObject{["key"]="fx_c71c2a84f3cc"}):corruptedFxIndex["visuals"]?[split[1]]?[split[2]] as JArray??new JArray();foreach(var row in art)PlaceCorrupted(wanted,"pulse-"+pulse.id+"-"+i++,(string)row["key"],0,World(pulse.position));}
        foreach(string id in corruptedAttachments.Keys.Where(id=>!wanted.Contains(id)).ToArray()){if(corruptedAttachments[id])Destroy(corruptedAttachments[id].gameObject);corruptedAttachments.Remove(id);}
    }
    void AuditCorruptedParticles(){int count=0;foreach(var prefab in ContentResources.LoadAll<GameObject>("CorruptedFx"))foreach(var renderer in prefab.GetComponentsInChildren<ParticleSystemRenderer>()){var material=renderer.sharedMaterial;if(!material||!material.shader||!material.shader.isSupported||!material.mainTexture)throw new InvalidOperationException("Invalid Corrupted particle material: "+prefab.name);count++;}Debug.Log("CF_CORRUPTED_PARTICLE_AUDIT_PASS materials="+count);}
    void ClearCorruptedViews(){corruptedAttachments.Clear();}
}
}
